        r'compact object', r'astrophys', r'galaxy', r'AGN'
    ],
    'DNA': [
        r'\bdna\b', r'deoxyribonucleic', r'genome', r'genomic', r'genetic', r'gene', r'chromosome', r'nucleotide',
        r'double helix', r'sequencing', r'base pair', r'genomics', r'\brna\b', r'crispr', r'transcription', r'replication'
    ],
    'music_history': [
        r'music', r'music history', r'musicology', r'composer', r'symphony', r'sonata', r'baroque', r'classical', r'romantic',
        r'medieval', r'renaissance', r'opera', r'orchestra', r'jazz', r'blues', r'folk', r'melody', r'harmony', r'rhythm',
        r'instrument', r'concert', r'genre', r'score', r'notation'
    ],
}

compiled = {k: [re.compile(p, re.IGNORECASE) for p in pats] for k, pats in keywords.items()}


def extract_text_pdf(path, max_pages=2):
    try:
        # Use pdftotext to stdout for first pages
        cmd = ['pdftotext', '-f', '1', '-l', str(max_pages), path, '-']
        res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, check=False)
        return res.stdout.decode('utf-8', errors='ignore')
    except Exception:
        return ''


def extract_text_docx(path):
    try:
        with zipfile.ZipFile(path) as z:
            xml = z.read('word/document.xml')
        root = ET.fromstring(xml)
        texts = []
        for node in root.iter():
            if node.tag.endswith('}t') and node.text:
                texts.append(node.text)
        return '\n'.join(texts)
    except Exception:
        return ''


def extract_text_pptx(path):
    texts = []
    try:
        with zipfile.ZipFile(path) as z:
            slide_files = sorted([n for n in z.namelist() if n.startswith('ppt/slides/slide') and n.endswith('.xml')])
            for name in slide_files:
                xml = z.read(name)
                root = ET.fromstring(xml)
                for node in root.iter():
                    if node.tag.endswith('}t') and node.text:
                        texts.append(node.text)
        return '\n'.join(texts)
    except Exception:
        return ''


def score_text(text):
    scores = {}
    for cat, pats in compiled.items():
        s = 0
        for pat in pats:
            s += len(pat.findall(text))
        scores[cat] = s
    return scores

results = []

for fname in sorted(os.listdir(root)):
    path = os.path.join(root, fname)
    if not os.path.isfile(path):
        continue
    ext = os.path.splitext(fname)[1].lower()
    text = ''
    if ext == '.pdf':
        text = extract_text_pdf(path, max_pages=2)
    elif ext == '.docx':
        text = extract_text_docx(path)
    elif ext == '.pptx':
        text = extract_text_pptx(path)
    else:
        text = ''

    text_low = text.lower()
    scores = score_text(text_low)
    # sort by score desc
    sorted_scores = sorted(scores.items(), key=lambda x: x[1], reverse=True)
    top_cat, top_score = sorted_scores[0]
    second_cat, second_score = sorted_scores[1]
    # heuristic: if all zero, mark uncertain
    results.append({
        'file': fname,
        'ext': ext,
        'top_cat': top_cat,
        'top_score': top_score,
        'second_cat': second_cat,
        'second_score': second_score,
    })

# save results
out_path = '/root/papers/classification.json'
with open(out_path, 'w') as f:
    json.dump(results, f, indent=2)

# print summary
from collections import Counter
cnt = Counter(r['top_cat'] for r in results)
print('Summary:')
for k, v in cnt.items():
    print(f'{k}: {v}')

# print uncertain (low score or tie)
uncertain = [r for r in results if r['top_score'] == 0 or r['top_score'] == r['second_score']]
print('\nUncertain:', len(uncertain))
for r in uncertain[:50]:
    print(f"{r['file']}: {r['top_cat']}({r['top_score']}) vs {r['second_cat']}({r['second_score']})")
